    Subject = apps.get_model('api', 'Subject')
    StudySession = apps.get_model('api', 'StudySession')

    groups = defaultdict(list)
    for subject in Subject.objects.all().order_by('id'):
        key = (subject.user_id, subject.name)
        groups[key].append(subject.id)

    to_delete = []
